package com.cuboland.app

import android.util.Base64
import java.util.zip.Inflater

/** Dados da vitrine MANSÃO (gerados por tools/mansao_gen.py): lista de comandos comprimida.
 *  F|bloco|x1|y1|z1|x2|y2|z2 = preenche; P|bloco|x|y|z = põe um; R|bloco|dir|x|y|z = telhado/escada virado (0=+Z,1=-Z,2=+X,3=-X);
 *  T|x|z|tipo|tronco|folha = árvore; L|x|y|z|grande|texto = placa. '-' = ar. Coordenadas relativas ao lote (y 0 = piso do térreo). */
object MansionData {
    private val Z = arrayOf(
        "",
        "",
        "",
        "",
        "",
    )
    fun lines(): List<String> {
        val z = Base64.decode(Z.joinToString(""), Base64.DEFAULT)
        val inf = Inflater(); inf.setInput(z)
        val bo = java.io.ByteArrayOutputStream(); val buf = ByteArray(8192)
        while (!inf.finished()) { val r = inf.inflate(buf); if (r <= 0) break; bo.write(buf, 0, r) }
        inf.end()
        return String(bo.toByteArray(), Charsets.UTF_8).split('\n')
    }
}
